// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./IERC7857Types.sol";

/// @title IERC7857Metadata
/// @notice Metadata extension for ERC-7857 intelligent NFTs.
interface IERC7857Metadata {
    /// @notice Collection name (ERC-721 compatible).
    function name() external view returns (string memory);

    /// @notice Collection symbol (ERC-721 compatible).
    function symbol() external view returns (string memory);

    /// @notice Returns all intelligent data records for a token.
    ///         Each record's `dataHash` is the 0G Storage root hash of the
    ///         encrypted payload currently accessible to the token owner.
    /// @param _tokenId  The token identifier.
    function intelligentDataOf(uint256 _tokenId)
        external
        view
        returns (IntelligentData[] memory);
}

contracts/interfaces/IERC7857Types.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice Oracle type for the verification system
enum OracleType { TEE, ZKP }

/// @notice Proof of data access — signed by the receiver (or their delegate)
struct AccessProof {
    bytes32 oldDataHash;     // Hash of the current (old) encrypted data
    bytes32 newDataHash;     // Hash of the new encrypted data (re-keyed for new owner)
    bytes   nonce;           // Replay-protection nonce
    bytes   encryptedPubKey; // New owner's public key, encrypted. Empty = use ETH pubkey.
    bytes   proof;           // TEE attestation or ZKP
}

/// @notice Proof of data ownership transfer
struct OwnershipProof {
    OracleType oracleType;   // TEE or ZKP
    bytes32 oldDataHash;
    bytes32 newDataHash;
    bytes   sealedKey;       // New data key, sealed for the new owner
    bytes   encryptedPubKey;
    bytes   nonce;
    bytes   proof;
}

/// @notice Combined proof required for iTransfer / iClone
struct TransferValidityProof {
    AccessProof   accessProof;
    OwnershipProof ownershipProof;
}

/// @notice Output returned by the on-chain verifier
struct TransferValidityProofOutput {
    bytes32 oldDataHash;
    bytes32 newDataHash;
    bytes   sealedKey;
    bytes   encryptedPubKey;
    bytes   wantedKey;
    address accessAssistant;
    bytes   accessProofNonce;
    bytes   ownershipProofNonce;
}

/// @notice Per-token intelligent data record (maps to 0G Storage root hash)
struct IntelligentData {
    string  dataDescription; // Human-readable label, e.g. "skill-payload"
    bytes32 dataHash;        // 0G Storage root hash of the encrypted payload
}

contracts/SkillFunOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title SkillFunOracle
 * @notice On-chain registry of verified GitHub → wallet mappings for SkillFun claim flow.
 *
 * Architecture:
 *  - The contract `owner` (and any approved `operators`) can call `setVerifiedClaims`.
 *  - Ownership is transferable via `transferOwnership(newOwner)` — the owner may
 *    hand control to a cold wallet at any time without redeployment.
 *  - The owner may grant/revoke operator status to additional hot-wallet addresses.
 *  - The SkillNFT contract (set once by the owner) can call `clearVerifiedClaim`
 *    after a successful claim, making each Oracle entry one-time-use.
 *  - `verifiedOwner[tokenId]` is the wallet address that is allowed to claim
 *    the NFT with the given tokenId.
 *
 * Security properties:
 *  - Only owner or operators can write verified claims.
 *  - Ownership is fully transferable to a cold wallet.
 *  - Each entry is cleared on claim, preventing replay.
 *  - All writes are on-chain and publicly auditable.
 */
contract SkillFunOracle is Ownable {
    // -------------------------------------------------------------------------
    // State
    // -------------------------------------------------------------------------

    /// @notice The SkillNFT contract address, the only entity allowed to clear
    ///         verified claims (called during `claim()`).
    address public skillNFT;

    /// @notice tokenId → verified wallet address allowed to claim.
    mapping(uint256 => address) public verifiedOwner;

    /// @notice Approved operator addresses that can call setVerifiedClaims.
    mapping(address => bool) public operators;

    // -------------------------------------------------------------------------
    // Events
    // -------------------------------------------------------------------------

    event VerifiedClaimsSet(uint256[] tokenIds, address[] owners);
    event VerifiedClaimCleared(uint256 indexed tokenId);
    event SkillNFTSet(address indexed skillNFT);
    event OperatorAdded(address indexed operator);
    event OperatorRemoved(address indexed operator);

    // -------------------------------------------------------------------------
    // Errors
    // -------------------------------------------------------------------------

    error OnlyAuthorized();
    error OnlySkillNFT();
    error ArrayLengthMismatch();
    error ZeroAddress();

    // -------------------------------------------------------------------------
    // Modifiers
    // -------------------------------------------------------------------------

    modifier onlyAuthorized() {
        if (msg.sender != owner() && !operators[msg.sender]) revert OnlyAuthorized();
        _;
    }

    // -------------------------------------------------------------------------
    // Constructor
    // -------------------------------------------------------------------------

    /// @param initialOwner The address that will own the contract on deployment.
    constructor(address initialOwner) Ownable(initialOwner) {
        if (initialOwner == address(0)) revert ZeroAddress();
    }

    // -------------------------------------------------------------------------
    // Owner: operator management
    // -------------------------------------------------------------------------

    /// @notice Approve an operator address to call setVerifiedClaims.
    function addOperator(address operator) external onlyOwner {
        if (operator == address(0)) revert ZeroAddress();
        operators[operator] = true;
        emit OperatorAdded(operator);
    }

    /// @notice Revoke an operator's access.
    function removeOperator(address operator) external onlyOwner {
        operators[operator] = false;
        emit OperatorRemoved(operator);
    }

    // -------------------------------------------------------------------------
    // Owner: SkillNFT wiring (updatable — onlyOwner is sufficient protection)
    // -------------------------------------------------------------------------

    /**
     * @notice Set or update the SkillNFT contract address.
     *         Only callable by the owner. Can be updated after initial set so that
     *         SkillNFT can be redeployed (e.g. when adding new features) without
     *         requiring a full Oracle redeployment.
     * @param _skillNFT Address of the deployed SkillNFT contract.
     */
    function setSkillNFT(address _skillNFT) external onlyOwner {
        if (_skillNFT == address(0)) revert ZeroAddress();
        skillNFT = _skillNFT;
        emit SkillNFTSet(_skillNFT);
    }

    // -------------------------------------------------------------------------
    // Oracle writes (owner or operator)
    // -------------------------------------------------------------------------

    /**
     * @notice Batch-write verified claim mappings. Callable by owner or operators.
     * @param tokenIds  Array of NFT token IDs.
     * @param owners    Array of wallet addresses authorised to claim each token.
     */
    function setVerifiedClaims(
        uint256[] calldata tokenIds,
        address[] calldata owners
    ) external onlyAuthorized {
        if (tokenIds.length != owners.length) revert ArrayLengthMismatch();

        for (uint256 i = 0; i < tokenIds.length; i++) {
            verifiedOwner[tokenIds[i]] = owners[i];
        }

        emit VerifiedClaimsSet(tokenIds, owners);
    }

    // -------------------------------------------------------------------------
    // SkillNFT writes (clearVerifiedClaim — one-time-use enforcement)
    // -------------------------------------------------------------------------

    /**
     * @notice Clear a verified claim entry after the NFT has been claimed.
     *         Only callable by the SkillNFT contract.
     * @param tokenId The token that was just claimed.
     */
    function clearVerifiedClaim(uint256 tokenId) external {
        if (msg.sender != skillNFT) revert OnlySkillNFT();
        delete verifiedOwner[tokenId];
        emit VerifiedClaimCleared(tokenId);
    }
}

contracts/SkillNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

import "./interfaces/IERC7857.sol";
import "./interfaces/IERC7857DataVerifier.sol";
import "./interfaces/IERC7857Types.sol";
import "./SkillFunOracle.sol";

/// @title SkillNFT
/// @notice Full ERC-7857 implementation for SkillFun — AI Skill NFTs with
///         private metadata anchored on 0G Storage.
///
/// ┌─────────────────────────────────────────────────────────────────┐
/// │  ERC-7857 compliance                                            │
/// │  • intelligentDataOf()  → 0G Storage rootHash per token        │
/// │  • iTransfer()          → proof-verified ownership transfer     │
/// │  • iClone()             → mint a new skill from an existing one │
/// │  • authorizeUsage()     → grant usage rights (not ownership)   │
/// │  • revokeAuthorization()→ revoke usage rights                  │
/// │                                                                 │
/// │  SkillFun extensions (on top of ERC-7857)                      │
/// │  • manifestOwner        → GitHub repo path, locked at mint      │
/// │  • basePrice            → W0G price per invocation (set at mint)│
/// │  • claim()              → Oracle-verified GitHub→wallet claim   │
/// │  • invokeSkill()        → ERC-20 W0G payment, direct to owner  │
/// └─────────────────────────────────────────────────────────────────┘
///
/// POC notes:
///  - TransferValidityProof verification is handled by a stub verifier.
///    Swap verifier address for a real 0G Compute TEE verifier in Step 4.
///  - invokeSkill() pulls W0G from caller via transferFrom — caller must
///    approve SkillNFT for at least basePrice[tokenId] before calling.
///  - iClone() mints a new token but does not duplicate 0G Storage data;
///    the caller must supply a fresh rootHash for the clone.
contract SkillNFT is ERC721, ERC721URIStorage, Ownable, IERC7857 {

    // ─────────────────────────────────────────────────────────────────
    // State
    // ─────────────────────────────────────────────────────────────────

    /// @notice The Oracle that maps tokenId → verified claimer wallet.
    ///         Mutable so the platform can upgrade the Oracle without full redeployment.
    SkillFunOracle public oracle;

    /// @notice The ERC-7857 data verifier (stub in POC; real TEE in Step 4).
    IERC7857DataVerifier public verifier;

    /// @notice W0G ERC-20 token — used for skill invocation payments.
    IERC20 public immutable w0g;

    uint256 private _nextTokenId;

    /// @notice tokenId → GitHub repo path (e.g. "alice/weather-skill").
    ///         Locked at mint. Used by backend to verify claim eligibility.
    mapping(uint256 => string) public manifestOwner;

    /// @notice tokenId → invocation price in W0G wei. Set at mint, paid to
    ///         current NFT owner on each invokeSkill() call.
    mapping(uint256 => uint256) public basePrice;

    /// @notice ERC-7857: tokenId → array of intelligent data records.
    ///         Each record's dataHash is the current 0G Storage rootHash.
    mapping(uint256 => IntelligentData[]) private _intelligentData;

    /// @notice ERC-7857: tokenId → user → usage authorization.
    mapping(uint256 => mapping(address => bool)) private _authorized;

    // ─────────────────────────────────────────────────────────────────
    // Events (SkillFun extensions)
    // ─────────────────────────────────────────────────────────────────

    event SkillRegistered(
        uint256 indexed tokenId,
        string  repoUrl,
        string  skillURI,
        bytes32 rootHash
    );
    event SkillClaimed(
        uint256 indexed tokenId,
        address indexed claimer
    );
    event SkillInvoked(
        uint256 indexed tokenId,
        address indexed caller,
        uint256 value
    );
    /// @notice Emitted when the 0G Storage rootHash is updated (e.g. after
    ///         proxy re-encryption during a claim or iTransfer).
    event DataHashUpdated(
        uint256 indexed tokenId,
        bytes32 oldHash,
        bytes32 newHash
    );
    /// @notice Emitted when the NFT owner updates the invocation base price.
    event BasePriceUpdated(
        uint256 indexed tokenId,
        uint256 oldPrice,
        uint256 newPrice
    );

    // ─────────────────────────────────────────────────────────────────
    // Errors
    // ─────────────────────────────────────────────────────────────────

    error NotVerifiedClaimer();
    error AlreadyClaimed();
    error NotTokenOwner();
    error NotOwnerOrAuthorized();
    error ProofLengthMismatch();

    // ─────────────────────────────────────────────────────────────────
    // Constructor
    // ─────────────────────────────────────────────────────────────────

    /// @param _oracle    Address of the deployed SkillFunOracle.
    /// @param _verifier  Address of the ERC-7857 data verifier (stub for POC).
    /// @param _owner     Platform deployer — receives Ownable ownership.
    /// @param _w0g       Address of the W0G ERC-20 token (Wrapped 0G).
    constructor(address _oracle, address _verifier, address _owner, address _w0g)
        ERC721("SkillFun Skill", "SKILL")
        Ownable(_owner)
    {
        oracle   = SkillFunOracle(_oracle);
        verifier = IERC7857DataVerifier(_verifier);
        w0g      = IERC20(_w0g);
    }

    // ─────────────────────────────────────────────────────────────────
    // SkillFun: Mint
    // ─────────────────────────────────────────────────────────────────

    /// @notice Register a skill — open to anyone.
    ///
    /// @param repoUrl    GitHub repo path — becomes manifestOwner, locked forever.
    /// @param skillURI   Metadata URI (points to manifest on 0G Storage).
    /// @param rootHash   0G Storage root hash of the encrypted skill payload.
    ///                   Stored as the first IntelligentData entry.
    /// @param to         Recipient of the minted NFT.
    ///                   • Pass your own address  → you own the iNFT immediately ("My Repo").
    ///                   • Pass address(this)     → NFT held by contract until the real
    ///                                              GitHub owner calls claim() ("Not My Repo").
    /// @param _basePrice W0G amount (in wei) agents must pay per invokeSkill() call.
    ///                   Pass 0 for a free skill.
    /// @return tokenId   The minted token ID.
    function registerSkill(
        string  calldata repoUrl,
        string  calldata skillURI,
        bytes32          rootHash,
        address          to,
        uint256          _basePrice
    ) external returns (uint256 tokenId) {
        require(to != address(0), "SkillNFT: to is zero address");
        tokenId = _nextTokenId++;
        manifestOwner[tokenId] = repoUrl;
        basePrice[tokenId]     = _basePrice;

        _safeMint(to, tokenId);
        _setTokenURI(tokenId, skillURI);

        // Anchor the 0G Storage rootHash as ERC-7857 IntelligentData
        _intelligentData[tokenId].push(IntelligentData({
            dataDescription: "skill-payload",
            dataHash:        rootHash
        }));

        emit SkillRegistered(tokenId, repoUrl, skillURI, rootHash);
    }

    // ─────────────────────────────────────────────────────────────────
    // Admin: Oracle pointer update
    // ─────────────────────────────────────────────────────────────────

    /// @notice Update the Oracle contract address. Only callable by the owner.
    ///         Allows upgrading the Oracle without full contract redeployment.
    function setOracle(address _oracle) external onlyOwner {
        require(_oracle != address(0), "SkillNFT: zero address");
        oracle = SkillFunOracle(_oracle);
    }

    // ─────────────────────────────────────────────────────────────────
    // SkillFun: Oracle Claim
    // ─────────────────────────────────────────────────────────────────

    /// @notice Claim an NFT from contract custody.
    ///         Caller must be the address the cold wallet registered in the Oracle.
    ///         After a successful claim the caller should call updateDataHash()
    ///         once 0G Storage proxy re-encryption is complete (Step 4).
    /// @param tokenId  The token to claim.
    function claim(uint256 tokenId) external {
        if (ownerOf(tokenId) != address(this)) revert AlreadyClaimed();

        address verified = oracle.verifiedOwner(tokenId);
        if (verified == address(0) || verified != msg.sender) {
            revert NotVerifiedClaimer();
        }

        _transfer(address(this), msg.sender, tokenId);
        oracle.clearVerifiedClaim(tokenId);

        emit SkillClaimed(tokenId, msg.sender);
    }

    // ─────────────────────────────────────────────────────────────────
    // SkillFun: Curator Authorization
    // ─────────────────────────────────────────────────────────────────

    /// @notice Authorize yourself to use an unclaimed skill (NFT held by this
    ///         contract). Free — no payment required.
    ///         Reverts if the skill has already been claimed by its creator.
    /// @param tokenId  The unclaimed skill to authorize.
    function selfAuthorize(uint256 tokenId) external {
        require(
            ownerOf(tokenId) == address(this),
            "SkillNFT: skill is claimed, use purchaseAuthorization"
        );
        _authorized[tokenId][msg.sender] = true;
        emit Authorization(address(this), msg.sender, tokenId);
    }

    /// @notice Authorize yourself to use a claimed skill by paying basePrice
    ///         W0G to the current NFT owner. Caller must have approved this
    ///         contract for at least basePrice[tokenId] W0G before calling.
    ///         Pass 0-price skills also work (no approve needed).
    /// @param tokenId  The claimed skill to authorize.
    function purchaseAuthorization(uint256 tokenId) external {
        address owner_ = ownerOf(tokenId);
        require(
            owner_ != address(this),
            "SkillNFT: skill is unclaimed, use selfAuthorize"
        );
        uint256 price = basePrice[tokenId];
        if (price > 0) {
            require(
                w0g.transferFrom(msg.sender, owner_, price),
                "SkillNFT: W0G transfer failed"
            );
        }
        _authorized[tokenId][msg.sender] = true;
        emit Authorization(owner_, msg.sender, tokenId);
    }

    // ─────────────────────────────────────────────────────────────────
    // SkillFun: Invoke (x402 stub)
    // ─────────────────────────────────────────────────────────────────

    /// @notice Invoke a skill. Pulls W0G from caller directly to the current
    ///         NFT owner. Caller must have approved this contract for at least
    ///         basePrice[tokenId] W0G before calling.
    ///         Owner or any address authorized via authorizeUsage() may call this.
    /// @param tokenId  The skill NFT to invoke.
    function invokeSkill(uint256 tokenId) external {
        address owner_ = ownerOf(tokenId); // reverts if not minted
        if (owner_ != msg.sender && !_authorized[tokenId][msg.sender]) {
            revert NotOwnerOrAuthorized();
        }
        uint256 price = basePrice[tokenId];
        if (price > 0) {
            // Transfer W0G from caller → NFT owner (direct, no platform cut in POC)
            require(
                w0g.transferFrom(msg.sender, owner_, price),
                "SkillNFT: W0G transfer failed"
            );
        }
        emit SkillInvoked(tokenId, msg.sender, price);
    }

    // ─────────────────────────────────────────────────────────────────
    // ERC-7857: iTransfer
    // ─────────────────────────────────────────────────────────────────

    /// @inheritdoc IERC7857
    /// @dev POC: stub verifier accepts any proof (including empty array).
    ///      Step 4 replaces verifier with 0G Compute TEE contract.
    ///      After iTransfer, call updateDataHash() with the new rootHash
    ///      once 0G Storage proxy re-encryption completes.
    function iTransfer(
        address _to,
        uint256 _tokenId,
        TransferValidityProof[] calldata _proofs
    ) external override {
        if (ownerOf(_tokenId) != msg.sender) revert NotTokenOwner();

        IntelligentData[] storage data = _intelligentData[_tokenId];
        if (_proofs.length != 0 && _proofs.length != data.length) {
            revert ProofLengthMismatch();
        }

        // Verify proofs (stub: no-op, returns empty outputs)
        if (_proofs.length > 0) {
            TransferValidityProofOutput[] memory outputs =
                verifier.verifyTransferValidity(_proofs);
            // Update data hashes from verifier output when provided
            for (uint256 i = 0; i < outputs.length; i++) {
                if (outputs[i].newDataHash != bytes32(0)) {
                    bytes32 old = data[i].dataHash;
                    data[i].dataHash = outputs[i].newDataHash;
                    emit DataHashUpdated(_tokenId, old, outputs[i].newDataHash);
                }
            }
        }

        _transfer(msg.sender, _to, _tokenId);
        emit Transferred(_tokenId, msg.sender, _to);
    }

    // ─────────────────────────────────────────────────────────────────
    // ERC-7857: iClone
    // ─────────────────────────────────────────────────────────────────

    /// @inheritdoc IERC7857
    /// @dev Mints a new token. The first proof's newDataHash (if non-zero)
    ///      is used as the clone's initial rootHash. Supply a fresh 0G
    ///      Storage rootHash via the proof or call updateDataHash() after.
    function iClone(
        address _to,
        uint256 _tokenId,
        TransferValidityProof[] calldata _proofs
    ) external override returns (uint256 _newTokenId) {
        if (ownerOf(_tokenId) != msg.sender) revert NotTokenOwner();

        _newTokenId = _nextTokenId++;

        // Derive initial rootHash from proof output (or inherit from source)
        bytes32 cloneHash = _intelligentData[_tokenId].length > 0
            ? _intelligentData[_tokenId][0].dataHash
            : bytes32(0);

        if (_proofs.length > 0) {
            TransferValidityProofOutput[] memory outputs =
                verifier.verifyTransferValidity(_proofs);
            if (outputs.length > 0 && outputs[0].newDataHash != bytes32(0)) {
                cloneHash = outputs[0].newDataHash;
            }
        }

        _safeMint(_to, _newTokenId);
        _setTokenURI(_newTokenId, tokenURI(_tokenId));

        _intelligentData[_newTokenId].push(IntelligentData({
            dataDescription: "skill-payload",
            dataHash:        cloneHash
        }));

        // Clone inherits the same manifestOwner (same GitHub source)
        manifestOwner[_newTokenId] = manifestOwner[_tokenId];
    }

    // ─────────────────────────────────────────────────────────────────
    // ERC-7857: Usage Authorization
    // ─────────────────────────────────────────────────────────────────

    /// @inheritdoc IERC7857
    function authorizeUsage(uint256 _tokenId, address _user) external override {
        if (ownerOf(_tokenId) != msg.sender) revert NotTokenOwner();
        _authorized[_tokenId][_user] = true;
        emit Authorization(msg.sender, _user, _tokenId);
    }

    /// @inheritdoc IERC7857
    function revokeAuthorization(uint256 _tokenId, address _user) external override {
        if (ownerOf(_tokenId) != msg.sender) revert NotTokenOwner();
        _authorized[_tokenId][_user] = false;
        emit AuthorizationRevoked(msg.sender, _user, _tokenId);
    }

    /// @notice Check whether `user` has usage authorization for `tokenId`.
    function isAuthorized(uint256 tokenId, address user) external view returns (bool) {
        return _authorized[tokenId][user];
    }

    // ─────────────────────────────────────────────────────────────────
    // ERC-7857 Metadata: intelligentDataOf
    // ─────────────────────────────────────────────────────────────────

    /// @inheritdoc IERC7857Metadata
    function intelligentDataOf(uint256 _tokenId)
        external
        view
        override
        returns (IntelligentData[] memory)
    {
        return _intelligentData[_tokenId];
    }

    // ─────────────────────────────────────────────────────────────────
    // Data hash management (called after 0G Storage events)
    // ─────────────────────────────────────────────────────────────────

    /// @notice Update the W0G invocation price for a skill.
    ///         Only the current NFT owner may call this.
    ///         Curators who have already authorized will continue to work at
    ///         the price they paid; the new price applies to new authorizations.
    /// @param tokenId   Token to update.
    /// @param newPrice  New W0G amount in wei. Pass 0 to make the skill free.
    function setBasePrice(uint256 tokenId, uint256 newPrice) external {
        if (ownerOf(tokenId) != msg.sender) revert NotTokenOwner();
        uint256 old = basePrice[tokenId];
        basePrice[tokenId] = newPrice;
        emit BasePriceUpdated(tokenId, old, newPrice);
    }

    /// @notice Update the 0G Storage rootHash for a token.
    ///         Called by the token owner after proxy re-encryption completes
    ///         (e.g. after claim, or after a manual iTransfer).
    /// @param tokenId   Token to update.
    /// @param newHash   New 0G Storage root hash.
    /// @param index     Index in the IntelligentData array (0 for "skill-payload").
    function updateDataHash(
        uint256 tokenId,
        bytes32 newHash,
        uint256 index
    ) external {
        if (ownerOf(tokenId) != msg.sender) revert NotTokenOwner();
        bytes32 old = _intelligentData[tokenId][index].dataHash;
        _intelligentData[tokenId][index].dataHash = newHash;
        emit DataHashUpdated(tokenId, old, newHash);
    }

    /// @notice An authorized curator may update the data hash of an *unclaimed*
    ///         skill (one still held by this contract in platform custody).
    ///         Once the creator claims the NFT this function reverts — from that
    ///         point only the NFT owner can call updateDataHash().
    ///
    ///         Rationale: curators who have self-authorized for an unclaimed skill
    ///         are the natural party to keep its 0G Storage pointer fresh.
    ///         The price lock is intentional — basePrice is immutable until claimed.
    ///
    /// @param tokenId   Token to update (must be unclaimed).
    /// @param newHash   New 0G Storage root hash.
    /// @param index     Index in the IntelligentData array (0 for "skill-payload").
    function authorizedUpdateDataHash(
        uint256 tokenId,
        bytes32 newHash,
        uint256 index
    ) external {
        require(
            ownerOf(tokenId) == address(this),
            "SkillNFT: skill is claimed, use updateDataHash"
        );
        require(
            _authorized[tokenId][msg.sender],
            "SkillNFT: caller is not authorized for this skill"
        );
        bytes32 old = _intelligentData[tokenId][index].dataHash;
        _intelligentData[tokenId][index].dataHash = newHash;
        emit DataHashUpdated(tokenId, old, newHash);
    }

    /// @notice Platform owner can update verifier address (e.g. upgrade to real TEE).
    function setVerifier(address _verifier) external onlyOwner {
        verifier = IERC7857DataVerifier(_verifier);
    }

    // ─────────────────────────────────────────────────────────────────
    // ERC-721 receiver — allows this contract to hold its own NFTs
    // ─────────────────────────────────────────────────────────────────

    function onERC721Received(
        address, address, uint256, bytes calldata
    ) external pure returns (bytes4) {
        return this.onERC721Received.selector;
    }

    // ─────────────────────────────────────────────────────────────────
    // supportsInterface — declares ERC-7857 compliance
    // ─────────────────────────────────────────────────────────────────

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, ERC721URIStorage, IERC165)
        returns (bool)
    {
        return
            interfaceId == type(IERC7857).interfaceId          ||
            interfaceId == type(IERC7857Metadata).interfaceId  ||
            super.supportsInterface(interfaceId);
    }

    // ─────────────────────────────────────────────────────────────────
    // Required overrides
    // ─────────────────────────────────────────────────────────────────

    function tokenURI(uint256 tokenId)
        public view
        override(ERC721, ERC721URIStorage)
        returns (string memory)
    {
        return super.tokenURI(tokenId);
    }

    function name()
        public view
        override(ERC721, IERC7857Metadata)
        returns (string memory)
    {
        return super.name();
    }

    function symbol()
        public view
        override(ERC721, IERC7857Metadata)
        returns (string memory)
    {
        return super.symbol();
    }
}

